import { FileCode, type LucideIcon } from '@lucide/svelte';
import AlignCenter from '@lucide/svelte/icons/align-center';
import AlighJustify from '@lucide/svelte/icons/align-justify';
import AlignLeft from '@lucide/svelte/icons/align-left';
import AlignRight from '@lucide/svelte/icons/align-right';
import Audio from '@lucide/svelte/icons/audio-lines';
import Bold from '@lucide/svelte/icons/bold';
import Code from '@lucide/svelte/icons/code';
import IFrame from '@lucide/svelte/icons/code-xml';
import Heading1 from '@lucide/svelte/icons/heading-1';
import Heading2 from '@lucide/svelte/icons/heading-2';
import Heading3 from '@lucide/svelte/icons/heading-3';
import Heading4 from '@lucide/svelte/icons/heading-4';
import Image from '@lucide/svelte/icons/image';
import Italic from '@lucide/svelte/icons/italic';
import Link from '@lucide/svelte/icons/link-2';
import List from '@lucide/svelte/icons/list';
import ListChecks from '@lucide/svelte/icons/list-checks';
import ListOrdered from '@lucide/svelte/icons/list-ordered';
import Pilcrow from '@lucide/svelte/icons/pilcrow';
import Quote from '@lucide/svelte/icons/quote';
import Radical from '@lucide/svelte/icons/radical';
import Redo from '@lucide/svelte/icons/redo-2';
import SquareRadical from '@lucide/svelte/icons/square-radical';
import StrikeThrough from '@lucide/svelte/icons/strikethrough';
import Subscript from '@lucide/svelte/icons/subscript';
import Superscript from '@lucide/svelte/icons/superscript';
import Table from '@lucide/svelte/icons/table';
import Underline from '@lucide/svelte/icons/underline';
import Undo from '@lucide/svelte/icons/undo-2';
import Video from '@lucide/svelte/icons/video';
import Workflow from '@lucide/svelte/icons/workflow';
import { isTextSelection } from '@tiptap/core';
import type { Node } from '@tiptap/pm/model';
import { ISMAC } from '../helpers.ts';
import { type Editor } from '../tiptap/index.ts';

export interface Command {
  name: string;
  icon: LucideIcon;
  tooltip: string;
  shortCut?: string;
  onClick?: (editor: Editor) => void;
  turnInto?: (editor: Editor, node: Node, pos: number) => void;
  isActive?: (editor: Editor) => boolean;
  clickable?: (editor: Editor) => boolean;
}

export const commands: Record<string, Command[]> = {
  'undo-redo': [
    {
      icon: Undo,
      name: 'undo',
      tooltip: 'Undo',
      shortCut: `${ISMAC ? '⌘' : 'Ctrl+'}Z`,
      onClick: (editor) => {
        editor.chain().focus().undo().run();
      },
      clickable: (editor) => {
        return editor.can().undo();
      }
    },
    {
      icon: Redo,
      name: 'redo',
      tooltip: 'Redo',
      shortCut: `${ISMAC ? '⌘' : 'Ctrl+'}Y`,
      onClick: (editor) => {
        editor.chain().focus().redo().run();
      },
      clickable: (editor) => {
        return editor.can().redo();
      }
    }
  ],
  headings: [
    {
      icon: Heading1,
      name: 'h1',
      tooltip: 'Heading 1',
      shortCut: `${ISMAC ? '⌘⌥' : 'Ctrl+Alt+'}1`,
      onClick: (editor) => {
        editor.chain().focus().toggleHeading({ level: 1 }).run();
      },
      turnInto: (editor, _, pos) => {
        editor.chain().setNodeSelection(pos).setHeading({ level: 1 }).run();
      },
      clickable: (editor) => {
        return editor.can().toggleHeading({ level: 1 });
      },
      isActive: (editor) => {
        return editor.isActive('heading', { level: 1 });
      }
    },
    {
      icon: Heading2,
      name: 'h2',
      tooltip: 'Heading 2',
      shortCut: `${ISMAC ? '⌘⌥' : 'Ctrl+Alt+'}2`,
      onClick: (editor) => {
        editor.chain().focus().toggleHeading({ level: 2 }).run();
      },
      turnInto: (editor, _, pos) => {
        editor.chain().setNodeSelection(pos).setHeading({ level: 2 }).run();
      },
      clickable: (editor) => {
        return editor.can().toggleHeading({ level: 2 });
      },
      isActive: (editor) => {
        return editor.isActive('heading', { level: 2 });
      }
    },
    {
      icon: Heading3,
      name: 'h3',
      tooltip: 'Heading 3',
      shortCut: `${ISMAC ? '⌘⌥' : 'Ctrl+Alt+'}3`,
      onClick: (editor) => {
        editor.chain().focus().toggleHeading({ level: 3 }).run();
      },
      turnInto: (editor, _, pos) => {
        editor.chain().setNodeSelection(pos).setHeading({ level: 3 }).run();
      },
      clickable: (editor) => {
        return editor.can().toggleHeading({ level: 3 });
      },
      isActive: (editor) => {
        return editor.isActive('heading', { level: 3 });
      }
    },
    {
      icon: Heading4,
      name: 'h4',
      tooltip: 'Heading 4',
      shortCut: `${ISMAC ? '⌘⌥' : 'Ctrl+Alt+'}4`,
      onClick: (editor) => {
        editor.chain().focus().toggleHeading({ level: 4 }).run();
      },
      turnInto: (editor, _, pos) => {
        editor.chain().setNodeSelection(pos).setHeading({ level: 4 }).run();
      },
      clickable: (editor) => {
        return editor.can().toggleHeading({ level: 4 });
      },
      isActive: (editor) => {
        return editor.isActive('heading', { level: 4 });
      }
    }
  ],
  'text-formatting': [
    {
      icon: Link,
      name: 'link',
      tooltip: 'Link',
      onClick: (editor) => {
        if (editor.isActive('link')) {
          editor.chain().focus().unsetLink().run();
        } else {
          const url = window.prompt('Enter the URL of the link:');
          if (url) {
            editor.chain().focus().toggleLink({ href: url }).run();
          }
        }
      },
      isActive: (editor) => {
        return editor.isActive('link');
      }
    },
    {
      icon: Pilcrow,
      name: 'paragraph',
      tooltip: 'Paragraph',
      shortCut: `${ISMAC ? '⌘⇧' : 'Ctrl+Shift+'}0`,
      onClick: (editor) => {
        editor.chain().focus().setParagraph().run();
      },
      turnInto: (editor, _, pos) => {
        editor.chain().setNodeSelection(pos).setParagraph().run();
      },
      clickable: (editor) => {
        return editor.can().setParagraph();
      },
      isActive: (editor) => {
        return editor.isActive('paragraph');
      }
    },
    {
      icon: Bold,
      name: 'bold',
      tooltip: 'Bold',
      shortCut: `${ISMAC ? '⌘' : 'Ctrl+'}B`,
      onClick: (editor) => {
        editor.chain().focus().toggleBold().run();
      },
      turnInto: (editor, _, pos) => {
        editor.chain().setNodeSelection(pos).setMark('bold').run();
      },
      clickable: (editor) => {
        return editor.can().toggleBold();
      },
      isActive: (editor) => {
        return editor.isActive('bold');
      }
    },
    {
      icon: Italic,
      name: 'italic',
      tooltip: 'Italic',
      shortCut: `${ISMAC ? '⌘' : 'Ctrl+'}I`,
      onClick: (editor) => {
        editor.chain().focus().toggleItalic().run();
      },
      turnInto: (editor, _, pos) => {
        editor.chain().setNodeSelection(pos).setMark('italic').run();
      },
      clickable: (editor) => {
        return editor.can().toggleItalic();
      },
      isActive: (editor) => {
        return editor.isActive('italic');
      }
    },
    {
      icon: Underline,
      name: 'underline',
      tooltip: 'Underline',
      shortCut: `${ISMAC ? '⌘' : 'Ctrl+'}U`,
      onClick: (editor) => {
        editor.chain().focus().toggleUnderline().run();
      },
      turnInto: (editor, _, pos) => {
        editor.chain().setNodeSelection(pos).setMark('underline').run();
      },
      clickable: (editor) => {
        return editor.can().toggleUnderline();
      },
      isActive: (editor) => {
        return editor.isActive('underline');
      }
    },
    {
      icon: StrikeThrough,
      name: 'strikethrough',
      tooltip: 'Strikethrough',
      shortCut: `${ISMAC ? '⌘⇧' : 'Ctrl+Shift+'}S`,
      onClick: (editor) => {
        editor.chain().focus().toggleStrike().run();
      },
      turnInto: (editor, _, pos) => {
        editor.chain().setNodeSelection(pos).setMark('strike').run();
      },
      clickable: (editor) => {
        return editor.can().toggleStrike();
      },
      isActive: (editor) => {
        return editor.isActive('strike');
      }
    },
    {
      icon: Quote,
      name: 'blockQuote',
      tooltip: 'Blockquote',
      shortCut: `${ISMAC ? '⌘⇧' : 'Ctrl+Shift+'}B`,
      onClick: (editor) => {
        editor.chain().focus().toggleBlockquote().run();
      },
      turnInto: (editor, _, pos) => {
        editor.chain().setNodeSelection(pos).toggleBlockquote().run();
      },
      clickable: (editor) => {
        return editor.can().toggleBlockquote();
      },
      isActive: (editor) => {
        return editor.isActive('blockquote');
      }
    },
    {
      icon: Code,
      name: 'code',
      tooltip: 'Code',
      shortCut: `${ISMAC ? '⌘' : 'Ctrl+'}E`,
      onClick: (editor) => {
        editor.chain().focus().toggleCode().run();
      },
      turnInto: (editor, _, pos) => {
        editor.chain().setNodeSelection(pos).toggleCodeBlock().run();
      },
      clickable: (editor) => {
        return editor.can().toggleCode();
      },
      isActive: (editor) => {
        return editor.isActive('code');
      }
    },
    {
      icon: FileCode,
      name: 'codeBlock',
      tooltip: 'Code Block',
      shortCut: `${ISMAC ? '⌘⌥' : 'Ctrl+Shift+'}C`,
      onClick: (editor) => {
        editor.chain().focus().toggleCodeBlock({ language: 'plaintext' }).run();
      },
      turnInto: (editor, _, pos) => {
        editor.chain().setNodeSelection(pos).toggleCodeBlock({ language: 'plaintext' }).run();
      },
      clickable: (editor) => {
        return editor.can().toggleCodeBlock({ language: 'plaintext' });
      },
      isActive: (editor) => {
        return editor.isActive('codeBlock');
      }
    },
    {
      icon: Superscript,
      name: 'superscript',
      tooltip: 'Superscript',
      shortCut: `${ISMAC ? '⌘' : 'Ctrl+'}.`,
      onClick: (editor) => {
        editor.chain().focus().toggleSuperscript().run();
      },
      clickable: (editor) => {
        return editor.can().toggleSuperscript();
      },
      isActive: (editor) => {
        return editor.isActive('superscript');
      }
    },
    {
      icon: Subscript,
      name: 'subscript',
      tooltip: 'Subscript',
      shortCut: `${ISMAC ? '⌘' : 'Ctrl+'},`,
      onClick: (editor) => {
        editor.chain().focus().toggleSubscript().run();
      },
      clickable: (editor) => {
        return editor.can().toggleSubscript();
      },
      isActive: (editor) => {
        return editor.isActive('subscript');
      }
    }
  ],
  alignment: [
    {
      icon: AlignLeft,
      name: 'align-left',
      tooltip: 'Align Left',
      shortCut: `${ISMAC ? '⌘⇧' : 'Ctrl+Shift+'}L`,
      onClick: (editor) => {
        editor.chain().focus().toggleTextAlign('left').run();
      },
      turnInto: (editor, _, pos) => {
        editor.chain().setNodeSelection(pos).toggleTextAlign('left').run();
      },
      clickable: (editor) => {
        return editor.can().toggleTextAlign('left');
      },
      isActive: (editor) => editor.isActive({ textAlign: 'left' })
    },
    {
      icon: AlignCenter,
      name: 'align-center',
      tooltip: 'Align Center',
      shortCut: `${ISMAC ? '⌘⇧' : 'Ctrl+Shift+'}E`,
      onClick: (editor) => {
        editor.chain().focus().toggleTextAlign('center').run();
      },
      turnInto: (editor, _, pos) => {
        editor.chain().setNodeSelection(pos).toggleTextAlign('center').run();
      },
      clickable: (editor) => {
        return editor.can().toggleTextAlign('center');
      },
      isActive: (editor) => editor.isActive({ textAlign: 'center' })
    },
    {
      icon: AlignRight,
      name: 'align-right',
      tooltip: 'Align Right',
      shortCut: `${ISMAC ? '⌘⇧' : 'Ctrl+Shift+'}R`,
      onClick: (editor) => {
        editor.chain().focus().toggleTextAlign('right').run();
      },
      turnInto: (editor, _, pos) => {
        editor.chain().setNodeSelection(pos).toggleTextAlign('right').run();
      },
      clickable: (editor) => {
        return editor.can().toggleTextAlign('right');
      },
      isActive: (editor) => editor.isActive({ textAlign: 'right' })
    },
    {
      icon: AlighJustify,
      name: 'align-justify',
      tooltip: 'Align Justify',
      shortCut: `${ISMAC ? '⌘⇧' : 'Ctrl+Shift+'}J`,
      onClick: (editor) => {
        editor.chain().focus().toggleTextAlign('justify').run();
      },
      turnInto: (editor, _, pos) => {
        editor.chain().setNodeSelection(pos).toggleTextAlign('justify').run();
      },
      clickable: (editor) => {
        return editor.can().toggleTextAlign('justify');
      },
      isActive: (editor) => editor.isActive({ textAlign: 'justify' })
    }
  ],
  lists: [
    {
      icon: List,
      name: 'bulletList',
      tooltip: 'Bullet List',
      shortCut: `${ISMAC ? '⌘⇧' : 'Ctrl+Shift+'}8`,
      onClick: (editor) => {
        editor.chain().focus().toggleBulletList().run();
      },
      turnInto: (editor, _, pos) => {
        editor.chain().setNodeSelection(pos).toggleBulletList().run();
      },
      isActive: (editor) => editor.isActive('bulletList')
    },
    {
      icon: ListOrdered,
      name: 'orderedList',
      tooltip: 'Ordered List',
      shortCut: `${ISMAC ? '⌘⇧' : 'Ctrl+Shift+'}7`,
      onClick: (editor) => {
        editor.chain().focus().toggleOrderedList().run();
      },
      turnInto: (editor, _, pos) => {
        editor.chain().setNodeSelection(pos).toggleOrderedList().run();
      },
      clickable: (editor) => {
        return editor.can().toggleOrderedList();
      },
      isActive: (editor) => {
        return editor.isActive('orderedList');
      }
    },
    {
      icon: ListChecks,
      name: 'taskList',
      tooltip: 'Task List',
      shortCut: `${ISMAC ? '⌘⇧' : 'Ctrl+Shift+'}9`,
      onClick: (editor) => {
        editor.chain().focus().toggleTaskList().run();
      },
      turnInto: (editor, _, pos) => {
        editor.chain().setNodeSelection(pos).toggleTaskList().run();
      },
      clickable: (editor) => {
        return editor.can().toggleTaskList();
      },
      isActive: (editor) => {
        return editor.isActive('taskList');
      }
    }
  ],
  media: [
    {
      icon: Image,
      name: 'image-placeholder',
      tooltip: 'Image',
      onClick: (editor) => {
        editor.chain().focus().insertMediaPlaceholder({ mediaType: 'image' }).run();
      },
      isActive: (editor) => editor.isActive('mediaPlaceholder', { mediaType: 'image' })
    },
    {
      icon: Video,
      name: 'video-placeholder',
      tooltip: 'Video',
      onClick: (editor) => {
        editor.chain().focus().insertMediaPlaceholder({ mediaType: 'video' }).run();
      },
      isActive: (editor) => editor.isActive('mediaPlaceholder', { mediaType: 'video' })
    },
    {
      icon: Audio,
      name: 'audio-placeholder',
      tooltip: 'Audio',
      onClick: (editor) => {
        editor.chain().focus().insertMediaPlaceholder({ mediaType: 'audio' }).run();
      },
      isActive: (editor) => editor.isActive('mediaPlaceholder', { mediaType: 'audio' })
    },
    {
      icon: IFrame,
      name: 'iframe-placeholder',
      tooltip: 'Iframe',
      onClick: (editor) => {
        editor.chain().focus().insertMediaPlaceholder({ mediaType: 'iframe' }).run();
      },
      isActive: (editor) => editor.isActive('mediaPlaceholder', { mediaType: 'iframe' })
    }
  ],
  table: [
    {
      icon: Table,
      name: 'table',
      tooltip: 'Table',
      onClick: (editor) => {
        if (editor.isActive('table')) {
          const del = confirm('Do you really want to delete this table??');
          if (del) {
            editor.chain().focus().deleteTable().run();
            return;
          }
        }
        editor.chain().focus().insertTable({ cols: 3, rows: 3, withHeaderRow: false }).run();
      },
      isActive: (editor) => editor.isActive('table')
    }
  ],
  math: [
    {
      icon: Radical,
      name: 'mathematics',
      tooltip: 'Inline Math',
      onClick: (editor) => {
        let latex = 'a^2 + b^2 = c^2';
        const chain = editor.chain().focus();
        if (isTextSelection(editor.view.state.selection)) {
          const { from, to } = editor.view.state.selection;
          latex = editor.view.state.doc.textBetween(from, to);
          chain.deleteRange({ from, to });
        }
        chain.insertInlineMath({ latex }).run();
      },
      isActive: (editor) => editor.isActive('inlineMath')
    },
    {
      icon: SquareRadical,
      name: 'blockMathematics',
      tooltip: 'Block Math',
      onClick: (editor) => {
        const latex = 'a^2 + b^2 = c^2';
        editor.chain().focus().insertBlockMath({ latex }).run();
      },
      isActive: (editor) => editor.isActive('blockMath')
    }
  ],
  diagram: [
    {
      icon: Workflow,
      name: 'mermaid',
      tooltip: 'Mermaid Diagram',
      onClick: (editor) => {
        editor.chain().focus().setMermaid(' ').run();
      },
      isActive: (editor) => editor.isActive('mermaid')
    }
  ]
};

export { default as Link } from './Link.svelte';
export { default as MathBlock } from './MathBlock.svelte';
export { default as MathInline } from './MathInline.svelte';
export { default as TableColMenu } from './TableCol.svelte';
export { default as TableRowMenu } from './TableRow.svelte';
export { default as BubbleMenu } from './BubbleMenu.svelte';

import type { Extensions } from '@tiptap/core';
import Highlight from '@tiptap/extension-highlight';
import { TaskItem, TaskList } from '@tiptap/extension-list';
import Mathematics from '@tiptap/extension-mathematics';
import Subscript from '@tiptap/extension-subscript';
import SuperScript from '@tiptap/extension-superscript';
import TextAlign from '@tiptap/extension-text-align';
import { Color, FontSize, TextStyle } from '@tiptap/extension-text-style';
import Typography from '@tiptap/extension-typography';
import { CharacterCount, Placeholder } from '@tiptap/extensions';
import { Markdown } from '@tiptap/markdown';
import StarterKit from '@tiptap/starter-kit';
import {
  Audio,
  ColorHighlighter,
  SelectAcrossAtoms,
  Table,
  TableCell,
  TableHeader,
  TableRow
} from './tiptap';

export default [
  StarterKit.configure({
    orderedList: {
      HTMLAttributes: {
        class: 'list-decimal'
      }
    },
    bulletList: {
      HTMLAttributes: {
        class: 'list-disc'
      }
    },
    heading: {
      levels: [1, 2, 3, 4]
    },
    link: {
      openOnClick: false,
      autolink: true,
      linkOnPaste: true,
      HTMLAttributes: {
        target: '_blank',
        rel: 'noopener noreferrer nofollow'
      }
    },
    codeBlock: false
  }),
  Audio,
  CharacterCount,
  Highlight.configure({
    multicolor: true
  }),
  Placeholder.configure({
    emptyEditorClass: 'is-empty',
    // Use a placeholder:
    // Use different placeholders depending on the node type:
    placeholder: ({ node }) => {
      if (node.type.name === 'heading') {
        return "What's the title?";
      }
      if (node.type.name === 'paragraph') {
        return 'Type something...';
      }
      return '';
    }
  }),
  Color,
  Subscript,
  SuperScript,
  Typography,
  ColorHighlighter,
  TextStyle,
  FontSize,
  TextAlign.configure({
    types: ['heading', 'paragraph']
  }),
  TaskList,
  TaskItem.configure({
    nested: true
  }),
  // SearchAndReplace,
  Table,
  TableHeader,
  TableRow,
  TableCell,
  Markdown,
  Mathematics.configure({
    // Options for the KaTeX renderer. See here: https://katex.org/docs/options.html
    katexOptions: {
      throwOnError: true, // don't throw an error if the LaTeX code is invalid
      macros: {
        '\\R': '\\mathbb{R}', // add a macro for the real numbers
        '\\N': '\\mathbb{N}' // add a macro for the natural numbers
      }
    }
  }),
  // Drag-select across images/math/media; decorate selected atoms; keep selection on right-click
  SelectAcrossAtoms
] as Extensions;

@import "katex/dist/katex.min.css";
@import "./onedark.css";

.tiptap {
  margin-inline: auto;
}

.tiptap :first-child {
  margin-top: 0;
}

.tiptap :last-child {
  margin-bottom: 0;
}

.tiptap > p {
  margin: 1rem 0;
}

/* For Placeholder */
.tiptap .is-empty:not(blockquote.is-empty)::before {
  float: left;
  height: 0;
  color: var(--color-muted-foreground);
  pointer-events: none;
  content: attr(data-placeholder);
}

/* Heading Styles */
.tiptap h1,
.tiptap h2,
.tiptap h3,
.tiptap h4,
.tiptap h5,
.tiptap h6 {
  margin-top: 1rem;
  line-height: 1.2;
  text-wrap: pretty;
}

.tiptap h1,
.tiptap h2 {
  margin-top: 1rem;
  margin-bottom: 1rem;
}

.tiptap h1 {
  font-size: 2.25rem;
  font-weight: 800;
  line-height: 2.5rem;
  letter-spacing: -0.015em;
  scroll-margin: 5rem;
}

.tiptap h2 {
  font-size: 1.5rem;
  font-weight: 700;
}

.tiptap h3 {
  font-size: 1.25rem;
  font-weight: 600;
}

.tiptap h4,
.tiptap h5,
.tiptap h6 {
  font-size: 1rem;
  font-weight: 600;
}

.tiptap em {
  font-weight: 200;
}
.tiptap audio {
  width: 100%;
  display: block;
  margin: 1rem 0;
}

.tiptap blockquote {
  position: relative;
  padding: 0.25rem 0;
  padding-left: 0.75rem;
  margin: 1rem 0rem;
  font-style: italic;
  color: var(--color-muted-foreground);
}

.tiptap blockquote::before {
  position: absolute;
  top: 0;
  bottom: 0;
  left: 0;
  width: 0.2rem;
  content: " ";
  background-color: var(--color-border);
  border-radius: 0.5rem;
}

.tiptap blockquote p {
  margin: 0;
}

/* Horizontal Rule */
.tiptap hr {
  margin: 1.5rem 0;
  border: none;
  border-top: 1px solid var(--color-border);
}

.tiptap code:not(pre code) {
  font-family: "Fira Code Variable", monospace;
  font-size: 0.875em;
  background-color: var(--color-muted);
  color: var(--color-primary);
  border: 1px solid var(--color-border);
  padding: 0.125rem 0.25rem;
  border-radius: var(--radius-sm);
}

.tiptap pre {
  display: flex;
  height: fit-content;
  padding: 0 1rem 1rem 1rem;
  margin: 0;
  overflow: auto;
  background-color: transparent;
}

.tiptap pre code {
  flex: 1;
  padding: 0;
  color: inherit;
  background-color: transparent;
  border-radius: 0 !important;
}

.tiptap ul,
.tiptap ol {
  padding: 0;
  padding-left: 1.5rem;
  margin: 0.125rem 0;
}

.tiptap ul {
  list-style-type: disc;
}

.tiptap ol {
