import type { EditorOptions, Storage } from '@tiptap/core';
import { Editor as CoreEditor } from '@tiptap/core';
import type { EditorState, Plugin, PluginKey } from '@tiptap/pm/state';

export class Editor extends CoreEditor {
  public reactiveState: EditorState = this.view.state;

  public reactiveExtensionStorage: Storage = this.extensionStorage;

  constructor(options: Partial<EditorOptions> = {}) {
    super(options);

    this.reactiveState = this.view.state;
    this.reactiveExtensionStorage = this.extensionStorage;

    this.on('beforeTransaction', ({ nextState }) => {
      this.reactiveState = nextState;
      this.reactiveExtensionStorage = this.extensionStorage;
    });
  }

  get state() {
    return this.reactiveState ?? this.view.state;
  }

  get storage() {
    return this.reactiveExtensionStorage ?? super.storage;
  }

  public registerPlugin(
    plugin: Plugin,
    handlePlugins?: (newPlugin: Plugin, plugins: Plugin[]) => Plugin[]
  ): EditorState {
    const nextState = super.registerPlugin(plugin, handlePlugins);

    if (this.reactiveState) {
      this.reactiveState = nextState;
    }

    return nextState;
  }

  public unregisterPlugin(nameOrPluginKey: string | PluginKey): EditorState | undefined {
    const nextState = super.unregisterPlugin(nameOrPluginKey);

    if (this.reactiveState && nextState) {
      this.reactiveState = nextState;
    }

    return nextState;
  }
}

import { getContext, setContext } from 'svelte';
import type { Editor } from '../Editor.ts';

const EDITOR_CTX = Symbol('editor');

export const getEditor = (): Editor => {
  const editor = getContext<Editor>(EDITOR_CTX);

  if (!editor) {
    throw new Error('No editor found in context. Did you wrap your component in <Tiptap>?');
  }

  return editor;
};

export const setEditor = (editor: Editor): void => {
  setContext(EDITOR_CTX, editor);
};

import {
  mergeAttributes,
  Node,
  wrappingInputRule,
  type JSONContent,
  type MarkdownLexerConfiguration,
  type MarkdownParseHelpers,
  type MarkdownRendererHelpers,
  type MarkdownToken,
  type NodeViewProps
} from '@tiptap/core';
import type { Component } from 'svelte';
import { SvelteNodeViewRenderer } from '../renderers/SvelteNodeViewRenderer.ts';

declare module '@tiptap/core' {
  interface Commands<ReturnType> {
    callout: {
      setCallout: () => ReturnType;
    };
  }
}

export const Callout = (component: Component<NodeViewProps>) =>
  Node.create({
    name: 'callout',
    content: 'paragraph+',
    group: 'block',
    defining: true,
    selectable: true,
    draggable: true,

    addAttributes() {
      return {
        emoji: {
          default: '💡'
        }
      };
    },

    markdownTokenizer: {
      name: 'callout',
      level: 'block',

      start: (src: string) => {
        return src.indexOf('$');
      },

      tokenize: (src: string, _tokens: MarkdownToken[], lexer: MarkdownLexerConfiguration) => {
        // Match $callout[emoji]\ncontent\n$
        const match = /^\$callout\s*(.*)?\n([\s\S]*?)\n\$/.exec(src);

        if (!match) {
          return undefined;
        }

        return {
          type: 'callout',
          raw: match[0],
          emoji: match[1]?.trim() || '💡',
          text: match[2],
          tokens: lexer.blockTokens(match[2])
        };
      }
    },

    parseMarkdown: (token: MarkdownToken, helpers: MarkdownParseHelpers) => {
      return {
        type: 'callout',
        attrs: {
          emoji: token.emoji
        },
        content: helpers.parseChildren(token.tokens || [])
      };
    },

    renderMarkdown: (node: JSONContent, helpers: MarkdownRendererHelpers) => {
      const content = helpers.renderChildren(node);
      const emoji = node.attrs?.emoji || '💡';
      return `$callout${emoji}\n${content}\n$\n\n`;
    },

    addOptions() {
      return {
        HTMLAttributes: {
          class: 'callout'
        }
      };
    },

    parseHTML() {
      return [{ tag: 'div[class=callout]' }];
    },

    renderHTML({ HTMLAttributes }) {
      return ['div', mergeAttributes(this.options.HTMLAttributes, HTMLAttributes), 0];
    },

    addCommands() {
      return {
        setCallout:
          () =>
          ({ commands, editor }) => {
            const { type = null } = editor.getAttributes(this.name);
            if (type) {
              return commands.lift(this.name);
            } else {
              return commands.toggleWrap(this.name);
            }
          }
      };
    },

    addInputRules() {
      return [
        wrappingInputRule({
          find: /^\$callout\s*(.*)?\s$/,
          type: this.type,
          getAttributes: (match) => {
            return { emoji: match[1]?.trim() || '💡' };
          }
        })
      ];
    },

    addNodeView() {
      return SvelteNodeViewRenderer(component);
    }
  });

