export const Mermaid = (component: Component<NodeViewProps>) =>
  Node.create({
    name: 'mermaid',
    group: 'block',
    content: 'text*',
    atom: true,
    code: true,
    defining: true,
    isolating: true,
    draggable: true,

    addAttributes() {
      return {
        HTMLAttributes: {
          default: {}
        }
      };
    },

    markdownTokenizer: {
      name: 'mermaid',
      level: 'block',

      start: (src: string) => {
        return src.indexOf(':::');
      },

      tokenize: (src: string, _tokens: MarkdownToken[], lexer: MarkdownLexerConfiguration) => {
        // Match :::mermaid\ncontent\n:::
        const match = /^:::mermaid\n([\s\S]*?)\n:::/.exec(src);

        if (!match) {
          return undefined;
        }

        return {
          type: 'mermaid',
          raw: match[0],
          text: match[1], // Content
          tokens: lexer.blockTokens(match[1]) // Parse block content
        };
      }
    },

    parseMarkdown: (token: MarkdownToken, _helpers: MarkdownParseHelpers) => {
      return {
        type: 'mermaid',
        content: [
          {
            type: 'text',
            text: token.text ?? ''
          }
        ]
      };
    },
    renderMarkdown: (node: JSONContent, helpers: MarkdownRendererHelpers, _ctx: RenderContext) => {
      return `:::mermaid\n${helpers.renderChildren(node)}\n:::\n\n`;
    },

    parseHTML() {
      return [
        {
          tag: `div[data-type="${this.name}"]`,
          preserveWhitespace: 'full'
        }
      ];
    },

    renderHTML({ HTMLAttributes }) {
      return [
        'div',
        mergeAttributes({ 'data-type': this.name }, this.options.HTMLAttributes, HTMLAttributes),
        0
      ];
    },

    addCommands() {
      return {
        setMermaid:
          (code) =>
          ({ commands }) => {
            return commands.insertContent({
              type: this.name,
              content: [
                {
                  type: 'text',
                  text: code || ''
                }
              ]
            });
          }
      };
    },

    addInputRules() {
      return [
        textblockTypeInputRule({
          find: /^:::mermaid$/,
          type: this.type
        })
      ];
    },

    addNodeView() {
      return SvelteNodeViewRenderer(component);
    }
  });

