export const useEditor = (options: Partial<EditorOptions> = {}) => {
  let editor: Editor | undefined = undefined;

  if (isBrowser) {
    editor = new Editor(options);
  }

  $effect(() => {
    return () => {
      if (editor) {
        const nodes = editor.view.dom?.parentNode;
        const newEl = nodes?.cloneNode(true) as HTMLElement;
        nodes?.parentNode?.replaceChild(newEl, nodes);
        editor.destroy();
      }
    };
  });

  return editor;
};

import { type Readable, writable } from 'svelte/store';
import type { Editor } from '../Editor.ts';

export type EditorStateSnapshot = {
  editor: Editor;
};

const shallowEqual = (a: Record<string, unknown>, b: Record<string, unknown>) => {
  const aKeys = Object.keys(a);

  if (aKeys.length !== Object.keys(b).length) {
    return false;
  }

  for (const key of aKeys) {
    if (a[key] !== b[key]) {
      return false;
    }
  }

  return true;
};

export const useEditorState = <T extends Record<string, unknown>>({
  editor,
  selector
}: {
  editor: Editor;
  selector: (ctx: EditorStateSnapshot) => T;
}): Readable<T> => {
  const store = writable<T>(selector({ editor }));

  let subscriberCount = 0;

  const handleTransaction = () => {
    const next = selector({ editor });

    store.update((current) => {
      if (shallowEqual(current, next)) {
        return current;
      }

      return next;
    });
  };

  return {
    subscribe(run, invalidate) {
      subscriberCount += 1;

      if (subscriberCount === 1) {
        editor.on('transaction', handleTransaction);
      }

      const unsubscribe = store.subscribe(run, invalidate);

      return () => {
        unsubscribe();
        subscriberCount -= 1;

        if (subscriberCount === 0) {
          editor.off('transaction', handleTransaction);
        }
      };
    }
  };
};

import type { Editor } from '../Editor.ts';

/**
 * Svelte 5 rune-based hook that provides a reactive transaction counter.
 * Reading `version` inside a template expression creates a dependency
 * that re-evaluates on every editor transaction.
 */
export function useEditorTransaction(editor: Editor) {
  let version = $state(0);

  $effect(() => {
    const handler = () => {
      version++;
    };
    editor.on('transaction', handler);
    return () => {
      editor.off('transaction', handler);
    };
  });

  return {
    get version() {
      return version;
    }
  };
}

